package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ObjectBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class StringArrayDeserializer_createContextual_TriageGen1Test {

    private DeserializationContext ctxt;
    private BeanProperty property;
    private JavaType stringType;

    @Before
    public void setUp() {
        ctxt = mock(DeserializationContext.class);
        property = mock(BeanProperty.class);
        stringType = mock(JavaType.class);

        when(ctxt.constructType(String.class)).thenReturn(stringType);
    }

    /**
     * Test Case 1: When deser is null and findContextualValueDeserializer returns a non-default deserializer.
     * This covers the branch where findConvertingContentDeserializer returns null and deser != null after fallback.
     */
    @Test
    public void testCreateContextual_FallbackToContextualValueDeserializer() throws JsonMappingException {
        StringArrayDeserializer deserializer = new StringArrayDeserializer();
        // We need to inject a null _elementDeserializer via reflection or by ensuring findConvertingContentDeserializer returns null
        // Since we can't easily mock the protected findConvertingContentDeserializer without a spy, 
        // we assume the default state of _elementDeserializer is null.

        JsonDeserializer<?> mockDeser = mock(JsonDeserializer.class);
        when(ctxt.findContextualValueDeserializer(eq(stringType), eq(property))).thenReturn(mockDeser);

        JsonDeserializer<?> result = deserializer.createContextual(ctxt, property);

        assertNotNull(result);
        assertNotSame(deserializer, result);
        assertTrue(result instanceof StringArrayDeserializer);
    }

    /**
     * Test Case 2: When findConvertingContentDeserializer returns a deserializer, 
     * and it is NOT the default deserializer.
     * This covers the handleSecondaryContextualization branch.
     */
    @Test
    public void testCreateContextual_HandleSecondaryContextualization() throws JsonMappingException {
        // We use a spy to control the protected method findConvertingContentDeserializer
        StringArrayDeserializer spyDeserializer = spy(new StringArrayDeserializer());
        JsonDeserializer<?> mockDeser = mock(JsonDeserializer.class);
        JsonDeserializer<?> contextualizedDeser = mock(JsonDeserializer.class);

        // Injecting mockDeser into the spy is tricky because _elementDeserializer is private.
        // However, we can simulate the logic by mocking the findConvertingContentDeserializer call.
        doReturn(mockDeser).when(spyDeserializer).findConvertingContentDeserializer(any(), any(), any());
        when(ctxt.handleSecondaryContextualization(mockDeser, property)).thenReturn(contextualizedDeser);

        JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);

        assertNotNull(result);
        assertNotSame(spyDeserializer, result);
        assertTrue(result instanceof StringArrayDeserializer);
    }

    /**
     * Test Case 3: When the resulting deserializer is the default deserializer.
     * This covers the isDefaultDeserializer(deser) branch resulting in null.
     */
    @Test
    public void testCreateContextual_DefaultDeserializerReturnsNull() throws JsonMappingException {
        StringArrayDeserializer spyDeserializer = spy(new StringArrayDeserializer());

        // Mock findConvertingContentDeserializer to return a deserializer that is "default"
        // We simulate isDefaultDeserializer returning true.
        // Since isDefaultDeserializer is usually based on class type, we use a real String deserializer.
        JsonDeserializer<?> defaultDeser = new StringDeserializer(); 

        doReturn(defaultDeser).when(spyDeserializer).findConvertingContentDeserializer(any(), any(), any());
        // Note: In the actual code, if isDefaultDeserializer returns true, deser becomes null.
        // If deser is null, the code returns 'this' (the original deserializer).

        JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);

        assertEquals(spyDeserializer, result);
    }

    /**
     * Test Case 4: When no new deserializer is needed (deser == _elementDeserializer).
     * This covers the final return 'this' branch.
     */
    @Test
    public void testCreateContextual_ReturnsThisWhenNoChange() throws JsonMappingException {
        // To hit this, findConvertingContentDeserializer must return the same object as _elementDeserializer
        // and it must not be the default one.
        // This is hard with private fields, so we simulate the logic via a spy.

        StringArrayDeserializer spyDeserializer = spy(new StringArrayDeserializer());

        // We can't easily set _elementDeserializer, but if it's null, 
        // and findConvertingContentDeserializer returns null, 
        // and findContextualValueDeserializer returns null...
        when(ctxt.findContextualValueDeserializer(any(), any())).thenReturn(null);

        // If everything is null, the code flow:
        // deser = null -> findConvertingContentDeserializer returns null -> 
        // findContextualValueDeserializer returns null -> deser is null.
        // if (deser != null && ...) is skipped.
        // if (_elementDeserializer != deser) -> if (null != null) is false.
        // returns this.

        JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);

        assertEquals(spyDeserializer, result);
    }

    /**
     * Test Case 5: Test the exception propagation.
     */
    @Test(expected = JsonMappingException.class)
    public void testCreateContextual_ThrowsException() throws JsonMappingException {
        StringArrayDeserializer deserializer = new StringArrayDeserializer();
        when(ctxt.findContextualValueDeserializer(any(), any())).thenThrow(new JsonMappingException(null, "Error"));

        deserializer.createContextual(ctxt, property);
    }
}
